mapper.select:
SELECT ar.id, ar.audit_no AS auditNo, ar.business_id AS businessId, ar.applicant_id AS applicantId, u.name AS applicantName, CONCAT(LEFT(u.phone, 3), '****', RIGHT(u.phone, 4)) AS applicantPhone, ca.vehicle_number AS vehicleNumber, ca.car_name AS carName, ca.car_brand AS carBrand, ca.car_type AS carType, ar.current_status AS currentStatus, ar.priority, ar.submit_time AS submitTime, ar.create_time AS createTime FROM audit_record ar LEFT JOIN user_info u ON ar.applicant_id = u.id LEFT JOIN car_auth ca ON ar.business_id = ca.id WHERE ar.audit_type = 1 AND ar.is_deleted = 0
AND ar.current_status = #{query.status}
AND ar.priority = #{query.priority}
AND ( ca.vehicle_number LIKE CONCAT('%', #{query.keyword}, '%') OR u.name LIKE CONCAT('%', #{query.keyword}, '%') OR u.phone LIKE CONCAT('%', #{query.keyword}, '%') )
AND ar.submit_time >= #{query.startTime}
AND ar.submit_time <= #{query.endTime}
ORDER BY CASE ar.priority WHEN 3 THEN 0 WHEN 2 THEN 1 WHEN 1 THEN 2 ELSE 3 END, ar.submit_time DESC
